// src/api/config.js
import { IS_DEMO } from "./demoConfig";

// 실제 백엔드 주소 (운영 전환용)
export const BASE_URL = process.env.REACT_APP_API_BASE || "http://localhost:8080/api";

// 베이스 경로 계산: /woodenpages/ 같은 거
function computeFrontBase() {
  const cra = (typeof process !== "undefined" && process.env && process.env.PUBLIC_URL) || "";
  const vite = (typeof import.meta !== "undefined" && import.meta.env && import.meta.env.BASE_URL) || "";
  if (cra || vite) {
    const picked = cra || vite;
    return picked.endsWith("/") ? picked : picked + "/";
  }
  // 환경변수 없으면 현재 URL의 첫 세그먼트 사용
  const p = (typeof window !== "undefined" && window.location && window.location.pathname) || "/";
  const seg = p.split("/").filter(Boolean)[0];
  return seg ? `/${seg}/` : "/";
}

export const FRONT_BASE = computeFrontBase();

// 데모: 같은 오리진 + 베이스 경로로 보냄, 운영: 절대 URL
export const apiPath = (p) => {
  if (!p.startsWith("/")) p = "/" + p;
  return IS_DEMO
    ? `${FRONT_BASE.replace(/\/$/, "")}${p}` 
    : `${BASE_URL}${p}`;
};
